// Loads the bundled word lists (spec/01-engine.md 8.2, 12.1, 12.2). The files are generated by
// lexicon-builder from pinned inputs (ENG-R810); the engine core never embeds them (ENG-R812).
// Budget (ENG-R1231): at most 50 ms and 8 MB resident for all resources.

public import Foundation
public import VietnameseEngine

extension Resources {
    /// Why bundled or user-supplied resource files could not be loaded.
    public enum LoadError: Error, Sendable, Hashable, CustomStringConvertible {
        /// A required file (or the resource directory) does not exist.
        case missingResource(String)
        /// A file is unreadable as a whole (not UTF-8, bad manifest, wrong format version...).
        case malformedResource(String)
        /// One entry of a list breaks the format.
        case malformedEntry(resource: String, line: Int, reason: EntryProblem)
        /// The file does not match the size, entry count or SHA-256 recorded in manifest.json.
        case integrityMismatch(resource: String, detail: String)

        public enum EntryProblem: Sendable, Hashable {
            case emptyLine
            case missingFinalNewline
            case invalidCharacter
            case notNormalized
            case duplicate
            case wrongFieldCount
            case invalidDecision
            case invalidStatus
            case invalidHeader
            /// The `run` column of the ambiguity table is neither `en` nor `vi` (ENG-R827).
            case invalidRun
            /// The `viKind` column is not `particle`, `function` or `content` (ENG-R827).
            case invalidReadingKind
        }

        public var description: String {
            switch self {
            case .missingResource(let name): "missing resource \(name)"
            case .malformedResource(let detail): "malformed resource: \(detail)"
            case .malformedEntry(let resource, let line, let reason): "\(resource) line \(line): \(reason)"
            case .integrityMismatch(let resource, let detail): "\(resource) does not match manifest.json: \(detail)"
            }
        }
    }

    /// Loads the resources shipped in this package's bundle (`Bundle.module`) and adds the host's
    /// user lists (ENG-R860), macros (section 11), learned collision memory (ENG-R865) and never-correct list
    /// (ENG-R1118).
    public static func bundled(
        userKeepRaw: WordSet, userKeepVietnamese: WordSet, macros: MacroTable = .empty,
        collisionMemory: CollisionMemorySnapshot = .empty, userNeverCorrect: WordSet = WordSet([])
    ) throws -> Resources {
        guard let directory = bundledDirectory else { throw LoadError.missingResource("Resources") }
        return try load(
            from: directory, userKeepRaw: userKeepRaw, userKeepVietnamese: userKeepVietnamese, macros: macros,
            collisionMemory: collisionMemory, userNeverCorrect: userNeverCorrect)
    }

    /// Loads resource files in the bundled format from `directory` (manifest.json plus the lists).
    /// Used by `bundled` and by tests that need deliberately broken or tiny resource sets.
    /// The correction data of section 11A (ENG-R1120) is empty until the files of resource format 3 are built.
    public static func load(
        from directory: URL, userKeepRaw: WordSet, userKeepVietnamese: WordSet, macros: MacroTable = .empty,
        collisionMemory: CollisionMemorySnapshot = .empty, userNeverCorrect: WordSet = WordSet([])
    ) throws -> Resources {
        let files = try ResourceDirectory(directory)
        let ambiguity = try files.ambiguityTable()
        let tailWords = try files.wordList(.tailWords)
        let collision = CollisionLists(
            phrases: PhraseList(try files.wordList(.phrases)),
            supplement: WordSet(try files.wordList(.collisionSupplement)),
            boundaryParticles: WordSet(try files.wordList(.boundaryParticles)),
            runExempt: WordSet(ambiguity.runExempt), readingKinds: ambiguity.readingKinds,
            englishFunctionWords: WordSet(try files.wordList(.englishFunctionWords)),
            englishLean: WordSet(try files.wordList(.englishLean)), tailWords: WordSet(tailWords),
            tailParticles: WordSet(try files.wordList(.tailParticles)),
            preGuard: WordSet(try files.wordList(.preGuard)))
        return Resources(
            english: WordSet(try files.wordList(.english)),
            techAlways: WordSet(try files.wordList(.techAlways)),
            techCodeOnly: WordSet(try files.wordList(.techCodeOnly)),
            techCodeCapitalized: WordSet(try files.wordList(.techCodeCapitalized)),
            attestedSyllables: WordSet(try files.wordList(.attested)),
            ambiguity: ambiguity.decisions,
            userKeepRaw: userKeepRaw,
            userKeepVietnamese: userKeepVietnamese,
            macros: macros, collision: collision, collisionMemory: collisionMemory,
            userNeverCorrect: userNeverCorrect, correction: .empty)
    }

    /// The notices the host must show in its acknowledgements (ENG-R811): SCOWL's copyright and
    /// permission notice, the legal basis of the Vietnamese texts and the project lists' licence.
    public static func bundledNotices() throws -> String {
        guard let directory = bundledDirectory else { throw LoadError.missingResource("Resources") }
        return try ResourceDirectory(directory).notices()
    }

    static var bundledDirectory: URL? {
        Bundle.module.resourceURL?.appendingPathComponent("Resources", isDirectory: true)
    }
}
